// Failure classification, excerpts and redaction (SPEC 6.4). Pure: no `$` here.
import type { Failure, FailureClass } from './protocol.ts';

export const LIMITS = {
  call: 300,
  line: 240,
  outputLines: 12,
  evidenceLines: 5,
  excerpt: 400,
  /** The whole prompt or answer, when the fullPrompts option is on. */
  fullText: 20_000,
  text: 240,
  /** One activity-feed entry (#118). */
  activity: 300,
  /** A candidate older than this when its loop fails is not the cause. */
  candidateMaxAgeMs: 60_000,
} as const;

const SECRET_PATTERNS: RegExp[] = [
  /sk-ant-[A-Za-z0-9_-]{10,}/g,
  /ghp_[A-Za-z0-9]{20,}/g,
  /AKIA[0-9A-Z]{16}/g,
  /Bearer [A-Za-z0-9._-]{20,}/g,
];
// `password=hunter2`, `token: abc`, `"api_key": "abc"`: keep the key, redact the value.
const KEY_VALUE = /((?:password|passwd|token|secret|apikey|api_key)["']?\s*[=:]\s*["']?)([^\s"'&,;]+)/gi;

/** Replaces anything that looks like a secret with `[redacted]`. */
export function redact(text: string): string {
  let out = text;
  for (const re of SECRET_PATTERNS) out = out.replace(re, '[redacted]');
  return out.replace(KEY_VALUE, (_m, key: string) => `${key}[redacted]`);
}

/** Redacts, then cuts to `max` characters. */
export function clip(text: string, max: number): string {
  const r = redact(text);
  return r.length > max ? r.slice(0, max) : r;
}

/** The first 400 characters with whitespace collapsed, redacted. */
export function excerpt(text: string | null | undefined, max: number = LIMITS.excerpt): string {
  if (!text) return '';
  return clip(String(text).replace(/\s+/g, ' ').trim(), max);
}

const CUT_MARKER = '\n\n[cut off at 20,000 characters]';

/** The whole text redacted, line breaks kept, cut to 20,000 characters with a visible marker. */
export function fullText(text: string | null | undefined): string {
  if (!text) return '';
  const r = redact(String(text).replace(/\r\n?/g, '\n')).trim();
  return r.length > LIMITS.fullText ? r.slice(0, LIMITS.fullText) + CUT_MARKER : r;
}

/** The last `n` lines of a text, each redacted and cut to 240 characters. */
export function tailLines(text: string | null | undefined, n: number = LIMITS.outputLines): string[] {
  if (!text) return [];
  const lines = String(text).replace(/\r\n?/g, '\n').split('\n');
  while (lines.length && lines[lines.length - 1]!.trim() === '') lines.pop();
  return lines.slice(-n).map((l) => clip(l, LIMITS.line));
}

/** The exit code a Bash error result reports in its text ("Exit code 1"), best effort. */
export function parseExitCode(text: string | null | undefined): number | null {
  if (!text) return null;
  const m = /(?:exit code|exit status|exited with(?: code)?)[\s:]*(-?\d{1,3})\b/i.exec(text);
  return m ? Number(m[1]) : null;
}

/** Event fields that are the engine's own, not a tool's arguments. */
const ENGINE_KEYS = new Set(['tool', 'tool_use_id', 'agentId', 'requestMeta']);

/** A one-line summary of a tool call (SPEC 6.4): Bash -> the command; Edit/Read/Write -> tool + path. */
export function summarizeCall(tool: string, input: Record<string, unknown>): string {
  const str = (v: unknown) => (typeof v === 'string' ? v : v === undefined || v === null ? '' : JSON.stringify(v));
  let s: string;
  if (tool === 'Bash') s = str(input.command);
  else if (tool === 'Edit' || tool === 'Read' || tool === 'Write' || tool === 'NotebookEdit' || tool === 'MultiEdit') s = `${tool} ${str(input.file_path ?? input.notebook_path)}`.trim();
  else {
    const first = Object.entries(input).find(([k]) => !ENGINE_KEYS.has(k));
    s = first ? `${tool} ${str(first[1])}` : tool;
  }
  return clip(s.replace(/\s+/g, ' ').trim(), LIMITS.call);
}

/** How much raw text an activity entry is built from: more than enough for 300 characters after redaction, and a bound on the work. */
const ACTIVITY_RAW = 4000;
const FILE_TOOLS = new Set(['Edit', 'Read', 'Write', 'NotebookEdit', 'MultiEdit']);

/**
 * One activity-feed entry for a tool call (#118): the tool's name, a space, and a short summary of its arguments.
 * Bash: the command; file tools: the path; Grep: the pattern and where; Agent: the description; Skill: the skill;
 * anything else: its first argument. Redacted, whitespace collapsed, cut to 300 characters.
 */
export function activityCall(tool: string, input: Record<string, unknown>): string {
  const str = (v: unknown) => (typeof v === 'string' ? v : v === undefined || v === null ? '' : JSON.stringify(v) ?? '');
  let arg: string;
  if (tool === 'Bash') arg = str(input.command);
  else if (FILE_TOOLS.has(tool)) arg = str(input.file_path ?? input.notebook_path);
  else if (tool === 'Grep' || tool === 'Glob') arg = `${tool === 'Grep' ? `"${str(input.pattern)}"` : str(input.pattern)}${input.path ? ` in ${str(input.path)}` : ''}`;
  else if (tool === 'Agent') arg = str(input.description);
  else if (tool === 'Skill') arg = str(input.skill);
  else {
    const first = Object.entries(input).find(([k]) => !ENGINE_KEYS.has(k));
    arg = first ? str(first[1]) : '';
  }
  return clip(flatten(`${tool} ${arg}`), LIMITS.activity);
}

/**
 * Whitespace collapsed first, then cut to ACTIVITY_RAW, so redaction always sees whole what the entry can show: a
 * secret is never cut into a stub that no longer matches, even after a long run of whitespace before it.
 */
function flatten(text: string): string {
  return text.replace(/\s+/g, ' ').trim().slice(0, ACTIVITY_RAW);
}

/** One activity-feed entry for the text a model request wrote: whitespace collapsed, redacted, cut to 300 characters. Empty for text that is only whitespace. */
export function activityText(text: string): string {
  return clip(flatten(text), LIMITS.activity);
}

export interface FailureCandidate {
  at: number;
  tool: string;
  call: string;
  exitCode: number | null;
  outputTail: string[];
  denied: boolean;
  denyText: string | null;
}

/** Builds a candidate from a tool result that errored or was denied. */
export function candidateFrom(
  tool: string,
  input: Record<string, unknown>,
  result: { deny?: string; isError?: boolean; text?: string; result?: unknown },
  at: number,
): FailureCandidate | null {
  const denied = typeof result.deny === 'string';
  if (!denied && result.isError !== true) return null;
  const text = denied ? result.deny! : typeof result.text === 'string' ? result.text : typeof result.result === 'string' ? result.result : '';
  return {
    at,
    tool,
    call: summarizeCall(tool, input),
    exitCode: denied ? null : parseExitCode(text),
    outputTail: tailLines(text),
    denied,
    denyText: denied ? clip(text.replace(/\s+/g, ' ').trim(), LIMITS.line) : null,
  };
}

export type EndReason = 'answer' | 'aborted' | 'refusal' | 'error';

export interface ClassifyInput {
  reason: EndReason;
  candidate: FailureCandidate | null;
  /** The loop's last model stop reason. */
  stopReason: string | null;
  blowouts: number;
  now: number;
}

/**
 * The failure class for a loop that ended with `error`, `refusal` or `aborted` (SPEC 6.4); null for
 * `answer` (a loop that answered is done, and its candidate is discarded).
 *
 * Order: a denial, a refusal, an exhausted context window, an API error with no failing call, an
 * abort, then a tool error or Unknown. The window check comes before the API error because the
 * engine's `error` reason includes running out of context (see ARCHITECTURE.md, Spec questions).
 */
export function classify(i: ClassifyInput): FailureClass | null {
  if (i.reason === 'answer') return null;
  const fresh = i.candidate && i.now - i.candidate.at <= LIMITS.candidateMaxAgeMs ? i.candidate : null;
  if (fresh?.denied) return 'Blocked by permission';
  if (i.reason === 'refusal') return 'Refusal';
  if (i.stopReason === 'model_context_window_exceeded' || i.blowouts >= 3) return 'Context window exhausted';
  if (i.reason === 'error' && !fresh) return 'Model API error';
  if (i.reason === 'aborted') return 'Aborted';
  return fresh ? 'Tool error' : 'Unknown';
}

export interface EvidenceInput {
  blowoutTimes: number[];
  /** How often each failing call summary failed in this loop. */
  failedCalls: Record<string, number>;
  /** How often each file was read in this loop. */
  reads: Record<string, number>;
  denyText: string | null;
}

function hhmmss(t: number): string {
  const d = new Date(t);
  return [d.getHours(), d.getMinutes(), d.getSeconds()].map((v) => String(v).padStart(2, '0')).join(':');
}

/** Short facts the reporter observed; never invented. At most 5 lines. */
export function evidence(i: EvidenceInput): string[] {
  const out: string[] = [];
  if (i.blowoutTimes.length) {
    const n = i.blowoutTimes.length;
    out.push(`exceeded the context window ${n} time${n > 1 ? 's' : ''} (${i.blowoutTimes.slice(-3).map(hhmmss).join(', ')})`);
  }
  for (const [call, n] of Object.entries(i.failedCalls).sort((a, b) => b[1] - a[1])) {
    if (n >= 2) out.push(clip(`same call failed ${n} times: ${call}`, LIMITS.line));
  }
  for (const [file, n] of Object.entries(i.reads).sort((a, b) => b[1] - a[1])) {
    if (n >= 3) out.push(clip(`${file} read ${n} times`, LIMITS.line));
  }
  if (i.denyText) out.push(clip(`permission denied: ${i.denyText}`, LIMITS.line));
  return out.slice(0, LIMITS.evidenceLines);
}

export function buildFailure(cls: FailureClass, candidate: FailureCandidate | null, ev: string[], at: number, extra: { tool?: string; call?: string } = {}): Failure {
  return {
    class: cls,
    at,
    tool: candidate?.tool ?? extra.tool ?? null,
    call: candidate?.call ?? (extra.call ? clip(extra.call, LIMITS.call) : null),
    exitCode: candidate?.exitCode ?? null,
    outputTail: candidate ? candidate.outputTail.slice(-LIMITS.outputLines) : [],
    evidence: ev.slice(0, LIMITS.evidenceLines),
    explanation: null,
    retriedAs: null,
  };
}

/**
 * The prompt for an optional one-paragraph explanation (SPEC T5.2). Built only from the failure
 * record, which is already redacted and cut to its limits: never from the transcript.
 */
export function explainPrompt(f: Failure): string {
  const lines = [
    'A Claude Code agent failed. From this record alone, say in at most two short sentences what most likely went wrong and what would fix it. Plain text, no preamble, no markdown.',
    `Class: ${f.class}`,
    f.tool ? `Tool: ${f.tool}` : '',
    f.call ? `Call: ${f.call}` : '',
    f.exitCode !== null ? `Exit code: ${f.exitCode}` : '',
    f.outputTail.length ? `Last output lines:\n${f.outputTail.join('\n')}` : '',
    f.evidence.length ? `Observed:\n${f.evidence.map((e) => `- ${e}`).join('\n')}` : '',
  ];
  return redact(lines.filter(Boolean).join('\n'));
}

files.hooks/identity.ts:
/**
 * Which Podium identity (name and token) a session reports as (#226).
 *
 * The reporter's options are one set per Claude config directory, so two terminals on one machine share
 * them, and Claude Code reloads every session's module when an option changes. Reading the options
 * live would turn a running session into whoever signed in last. So a session takes its identity once
 * and holds it (in `$.state`, which survives a reload); a terminal can name its own through
 * `PODIUM_USER` and `PODIUM_TOKEN`, which win over the shared options.
 */

export interface Identity {
  userName: string;
  token: string;
}

export interface EnvIdentity {
  user?: string;
  token?: string;
}

/**
 * Whether an identity is worth holding for the rest of the session: it has a token. A name alone is not
 * signed in, so a token added later still applies; a session with no token has nothing to protect.
 */
export const worthHolding = (i: Identity): boolean => i.token !== '';

/**
 * The identity to report as: the one the session already holds, else the terminal's environment (taken
 * whole when either variable is set, never mixed with the shared options), else the shared options.
 * An identity without a token is not held (see worthHolding).
 */
export function pickIdentity(from: { held: Identity | undefined; env: EnvIdentity; options: Identity }): Identity {
  if (from.held && worthHolding(from.held)) return from.held;
  const user = (from.env.user ?? '').trim();
  const token = (from.env.token ?? '').trim();
  if (user || token) return { userName: user, token };
  return { userName: from.options.userName, token: from.options.token };
}

files.hooks/machine.ts:
// Which machine a session runs on (issue #34). Pure: the mod passes in what `hostname` printed and a
// random source. The id is random and kept in one file under the Claude config directory (and in the
// mod's own store as a fallback), so two machines that share a host name stay apart, two loads of the
// mod on one machine agree, and nothing about the hardware is read.
import type { MachineInfo } from './protocol.ts';
import { oneLine } from './peers.ts';

/** The `$.store` key the machine id is kept under. */
export const MACHINE_ID_KEY = 'machineId';
const HOST_MAX = 64;

/** The short host name from `hostname` output: the first line, up to the first dot (`Eds-MBP.local` is `Eds-MBP`). Null when empty. */
export function hostOf(stdout: string | null | undefined): string | null {
  const line = (stdout ?? '').split(/\r?\n/)[0] ?? '';
  // eslint-disable-next-line no-control-regex
  const host = line.replace(/[\u0000-\u001f\u007f]/g, '').trim().split('.')[0]!.trim();
  return host ? host.slice(0, HOST_MAX) : null;
}

/** `s` without the `/` characters at its end. A loop, not `/\/+$/`, which is quadratic on a long run of slashes (#362). */
export function trimTrailingSlashes(s: string): string {
  let end = s.length;
  while (end > 0 && s.charCodeAt(end - 1) === 47) end--;
  return s.slice(0, end);
}

/** A stored id this reporter made: 8 to 32 lowercase hex characters. */
export function isMachineId(v: unknown): v is string {
  return typeof v === 'string' && /^[0-9a-f]{8,32}$/.test(v);
}

/** The file name the machine id is shared under, in the Claude config directory (#267). */
export const MACHINE_ID_FILE = 'podium-machine-id';

/**
 * Where the shared machine id file lives: `CLAUDE_CONFIG_DIR` when set, else `~/.claude`. Null when
 * neither is known, in which case the id stays in the mod's store alone.
 */
export function machineIdPath(configDir: string | undefined, home: string | undefined): string | null {
  const trim = (p: string | undefined) => trimTrailingSlashes((p ?? '').trim());
  const dir = trim(configDir) || (trim(home) ? `${trim(home)}/.claude` : '');
  // A relative directory would land under each session's own working directory, so loads would disagree.
  return /^(\/|[A-Za-z]:[\\/])/.test(dir) ? `${dir}/${MACHINE_ID_FILE}` : null;
}

/** The id the shared file holds: its one line, when that is an id this reporter made. Null otherwise. */
export function parseMachineIdFile(text: string | null | undefined): string | null {
  const id = (text ?? '').trim();
  return isMachineId(id) ? id : null;
}

/** A new random id of 12 hex characters. */
export function newMachineId(random: () => number): string {
  let s = '';
  for (let i = 0; i < 12; i++) s += Math.floor(random() * 16).toString(16);
  return s;
}

/** The machine as the report carries it; a host with no name is labelled by its id. The OS is left out when it could not be read (#414). */
export function machineInfo(host: string | null, id: string, os: string | null = null): MachineInfo {
  return { name: host ?? `machine-${id.slice(0, 4)}`, id, ...(os ? { os } : {}) };
}

// ---- The OS (#347, #414, SPEC 5.3 "The OS") -----------------------------------------------------
// The mods API has no call for it, so the mod runs a command and takes the first that works.

/** The longest OS string a report carries (PEER_LIMITS.os). */
export const OS_MAX = 80;

/** One line of free text, without control characters, cut to 80. Null when nothing is left. */
export function cleanOs(v: string | null | undefined): string | null {
  return oneLine(v, OS_MAX) || null;
}

/** `sw_vers` on macOS: `ProductName` and `ProductVersion`, as `macOS 27.0.1`. Null without the name. */
export function osFromSwVers(stdout: string | null | undefined): string | null {
  const field = (key: string) => new RegExp(`^${key}:[ \\t]*(.+)$`, 'm').exec(stdout ?? '')?.[1]?.trim() ?? '';
  const name = field('ProductName');
  return name ? cleanOs(`${name} ${field('ProductVersion')}`) : null;
}

/** `/etc/os-release` on Linux: its `PRETTY_NAME`, quotes taken off. */
export function osFromOsRelease(text: string | null | undefined): string | null {
  const raw = /^PRETTY_NAME=(.*)$/m.exec(text ?? '')?.[1]?.trim() ?? '';
  return cleanOs(raw.replace(/^(["'])(.*)\1$/, '$2'));
}

/** `cmd /c ver` on Windows: its one non-empty line, such as `Microsoft Windows [Version 10.0.26100.1]`. */
export function osFromVer(stdout: string | null | undefined): string | null {
  return cleanOs((stdout ?? '').split(/\r?\n/).find((l) => l.trim()) ?? '');
}

files.hooks/protocol.ts:
// Report types for the Podium reporter (SPEC 6.2). Types only.
// The block between the PROTOCOL markers is identical to the one in server/src/fleet/protocol.ts;
// a server test compares the two after whitespace normalization, so edit both together.

// <protocol:begin>
export type Effort = 'low' | 'medium' | 'high' | 'xhigh' | 'max';

export type AgentStatus = 'queued' | 'running' | 'done' | 'failed' | 'aborted';

export type FailureClass =
  | 'Tool error'
  | 'Blocked by permission'
  | 'Model API error'
  | 'Refusal'
  | 'Context window exhausted'
  | 'Aborted'
  | 'Unknown';

export type EventKind =
  | 'start' | 'end' | 'spawn' | 'skill' | 'done' | 'fail' | 'blow' | 'compact' | 'plan' | 'wait' | 'note';

export interface TokenCounts {
  input: number;
  output: number;
  cacheRead: number;
  cacheWrite: number;
}

/** `cacheWrite` is the 5-minute cache write; `cacheWrite1h` the 1-hour one (0 when the reporter cannot split them). */
export interface UsageTokens extends TokenCounts {
  cacheWrite1h: number;
}

/**
 * One model's token totals, so the server prices them with the Admin's prices (issue #117). `tier` is `long`
 * for requests whose prompt (input + cache reads + cache writes) is over 100,000 tokens.
 */
export interface ModelUsage {
  model: string;
  tier: 'std' | 'long';
  tokens: UsageTokens;
}

export interface ContextFill {
  tokens: number | null;
  window: number | null;
  percent: number | null;
}

export interface GitInfo {
  branch: string | null;
  detached: boolean;
  isWorktree: boolean;
  worktreePath: string | null;
  ahead: number;
  behind: number;
  dirty: number;
}

export type FileStatus = 'added' | 'modified' | 'deleted' | 'renamed';

/** One file the session changed. `added` and `removed` are null for a binary file. */
export interface ChangedFile {
  path: string;
  status: FileStatus;
  added: number | null;
  removed: number | null;
  /** The old path of a renamed file. */
  from: string | null;
}

/**
 * What the session changed in its repository: the files (at most 200, by path) and the totals over
 * all of them. `since` says what the diff is against: the commit HEAD was at when the session began,
 * the merge base with the upstream branch when that commit is gone, or HEAD alone.
 */
export interface FilesReport {
  files: ChangedFile[];
  total: number;
  added: number;
  removed: number;
  since: 'start' | 'upstream' | 'worktree';
}

export interface RateLimit {
  kind: string;
  percentUsed: number;
  resetsAt: string | null;
}

export interface PlanStep {
  id: string;
  text: string;
  state: 'pending' | 'active' | 'done' | 'blocked';
  activeText: string | null;
  ownerAgentId: string | null;
  ownerLabel: string | null;
}

export interface Plan {
  title: string | null;
  source: 'TaskCreate' | 'TodoWrite' | 'podium_plan';
  steps: PlanStep[];
}

export interface Failure {
  class: FailureClass;
  at: number;
  tool: string | null;
  call: string | null;
  exitCode: number | null;
  outputTail: string[];
  evidence: string[];
  explanation: string | null;
  retriedAs: string | null;
}

/**
 * What the orchestrator's main loop reports about its own work, in the shapes an AgentReport uses for
 * the fields of the same name. Calls made by agents it launched are not counted here.
 */
export interface LoopReport {
  skills: string[];
  lastTool: string | null;
  toolCalls: number;
  toolCounts: Record<string, number>;
  steps: { done: number; total: null };
}

/** The loop key of the orchestrator's own feed, in the report reply's `watch` list and the activity route (#118). Engine agent ids never start with `@`. */
export const MAIN_LOOP = '@orchestrator';

/** The status of one file's diff, as the mod answers a request for it (#319, SPEC 6.4). */
export const FILE_DIFF_STATUSES = ['ok', 'binary', 'withheld', 'too-large', 'unavailable'] as const;
export type FileDiffStatus = (typeof FILE_DIFF_STATUSES)[number];

/** A diff the session's owner is waiting for, in the report reply's `diffs` list. */
export interface DiffRequest {
  id: string;
  path: string;
}

/** The mod's answer to a DiffRequest. `text` is a unified diff, redacted by the mod, and null for any status but `ok`. */
export interface FileDiffReply {
  path: string;
  status: FileDiffStatus;
  text: string | null;
  /** The mod cut the diff at a line or byte limit. */
  truncated: boolean;
  shownLines: number;
  totalLines: number;
  /** How many values the mod replaced with [redacted]. */
  redactions: number;
  /** What the diff is against: the short starting commit, the upstream merge base, or "worktree". null when there is none. */
  base: string | null;
}

/** `reasoning` is reserved for the model's thinking; the reporter does not send it. */
export type ActivityKind = 'tool' | 'text' | 'reasoning';

/**
 * One entry of a loop's activity feed (#118): a tool call (the tool's name, a space, and a short summary of its
 * arguments) or the text the model wrote in one step. Redacted and cut to 300 characters by the reporter. Sent only
 * with the `activityFeed` option on, and only for a loop the server's reply lists as watched.
 */
export interface ActivityEntry {
  at: number;
  kind: ActivityKind;
  text: string;
}

export interface AgentReport {
  id: string;
  parentId: string | null;
  kind: 'subagent' | 'fork' | 'teammate';
  type: string;
  name: string | null;
  description: string;
  model: string | null;
  effort: Effort | null;
  effortSource: 'requested' | 'observed' | 'inherited' | 'unknown';
  status: AgentStatus;
  startedAt: number;
  endedAt: number | null;
  context: ContextFill;
  tokens: TokenCounts;
  costUsdEst: number | null;
  /** Tokens per model and prompt-size tier. Absent when the reporter is too old to send it. */
  usageByModel?: ModelUsage[];
  skills: string[];
  lastTool: string | null;
  toolCalls: number;
  /** Finished calls per tool name. null when the reporter is too old to send it. */
  toolCounts: Record<string, number> | null;
  blowouts: number;
  steps: { done: number; total: number | null } | null;
  promptExcerpt: string;
  answerExcerpt: string | null;
  /**
   * The whole task prompt and final answer, redacted, line breaks kept. Sent only when the reporter's
   * `fullPrompts` option is on, and only once per text (the server keeps what it was given).
   */
  promptText?: string;
  answerText?: string;
  /** The agent's last 20 activity entries, oldest first: only while someone watches it, with the `activityFeed` option on (0.13.0 and later). */
  activity?: ActivityEntry[];
  failure: Failure | null;
}

export interface ActivityEvent {
  id: string;
  t: number;
  kind: EventKind;
  agentId: string | null;
  text: string;
  data: Record<string, unknown> | null;
}

/** What a session idle between turns is still waiting on: background work in flight, or a scheduled wake-up (#119). */
export type BackgroundKind = 'shell' | 'agent' | 'monitor' | 'workflow' | 'wakeup' | 'other';

export interface BackgroundTask {
  type: BackgroundKind;
  /** A short description; never a whole shell command. */
  description: string;
  status: string;
}

export interface BackgroundWait {
  tasks: BackgroundTask[];
  /** When the next scheduled wake-up fires (epoch ms); null when there is none or its time is unknown. */
  wakeAt: number | null;
}

export interface SessionReport {
  id: string;
  name: string;
  status: 'running' | 'waiting' | 'done';
  waitReason: 'permission' | 'input' | null;
  waitNote: string | null;
  endReason: string | null;
  resumeId: string | null;
  startedAt: number;
  cwd: string;
  projectRoot: string | null;
  repoName: string | null;
  git: GitInfo | null;
  model: string | null;
  effort: Effort | null;
  context: ContextFill;
  costUsd: number | null;
  tokens: TokenCounts;
  /** Tokens per model and tier for the whole session, agents included. Absent when the reporter is too old to send it. */
  usageByModel?: ModelUsage[];
  rateLimits: RateLimit[];
  blowouts: number;
  plan: Plan | null;
  /** The main loop's steps, tools and skills. null when the reporter is too old to send it. */
  loop: LoopReport | null;
  /** The files the session changed. null when the reporter is too old to send it. */
  files: FilesReport | null;
  /** Whether any client (a terminal, a phone) is attached. false for a background session left running after /exit. null when unknown: a reporter too old to send it. */
  attached: boolean | null;
  /** Background work the session is idle on. Absent from a reporter older than 0.11.0 and when there is none. */
  background?: BackgroundWait | null;
  /** Whether the reporter's `activityFeed` option is on. Absent from a reporter older than 0.13.0. */
  activityFeed?: boolean;
  /** Whether the reporter's `fileDiff` option is on (#319). Absent from a reporter older than the release that adds it. */
  fileDiff?: boolean;
  /** The main loop's last 20 activity entries, as on an agent: only while someone watches the orchestrator. */
  activity?: ActivityEntry[];
  /** Whether and how far the session can be answered from Podium (#206). Absent from a reporter older than 0.14.0. */
  respond?: RespondInfo;
  /** The asks open now, at most 8; sent only while the last reply said `respond: true`. */
  asks?: Ask[];
  /** The session id this one continues after a /clear (SPEC 5.8). */
  clearedFrom?: string | null;
  /** Whether the reporter's `peers` option is on (#347). Absent from a reporter older than the release that adds it, whose sessions are never listed as peers. */
  peers?: boolean;
}

export interface Report {
  v: 1;
  sentAt: number;
  /** `build` is the commit hash of a dev build of the mod (#400). A release, and a mod that predates it, leave it out. */
  reporter: { name: 'podium-reporter'; version: string; engineVersion: string | null; hostSurface: string | null; build?: string | null };
  session: SessionReport;
  agents: AgentReport[];
  events: ActivityEvent[];
  /** The person this reporter is configured as. The server checks it against the token's owner and refuses a mismatch. Omitted or null when none is set. */
  userName?: string | null;
  /** The machine the session runs on. Sent only with a userName, so nothing identifying leaves an unnamed reporter. Omitted or null from a reporter older than 0.9.0. */
  machine?: MachineInfo | null;
}

/** Which machine a session runs on: its host name, and a random id the reporter keeps so two machines with one host name stay apart. */
export interface MachineInfo {
  name: string;
  id: string;
  /** The machine's OS and version as the mod read it, such as `macOS 27.0.1` (#347). Free text, never parsed; absent or null when it could not be read. */
  os?: string | null;
}
/** "1 shell, 1 agent": the counts of a background wait by kind. The activity feed's wait row is read from it. */
export function backgroundSummary(b: BackgroundWait): string {
  const n = new Map<string, number>();
  for (const t of b.tasks) n.set(t.type, (n.get(t.type) ?? 0) + 1);
  return [...n].map(([k, c]) => `${c} ${k}`).join(', ');
}

/** A waiting session whose only wait is on background work or a wake-up, not on the person (#119). */
export function idleOnBackground<T extends { status: string; waitReason: string | null; background?: BackgroundWait | null }>(s: T): s is T & { background: BackgroundWait } {
  return s.status === 'waiting' && s.waitReason === null && !!s.background;
}

// ---- Responding (#206, SPEC 5.3, 6.2, 7.1) --------------------------------------------------

/** The reporter's `respond` option: what this session accepts from Podium. */
export type RespondLevel = 'off' | 'questions' | 'questions-and-plans' | 'everything';
export const RESPOND_LEVELS: readonly RespondLevel[] = ['off', 'questions', 'questions-and-plans', 'everything'];

/** One kind of answer a session can take from Podium. */
export type RespondKind = 'question' | 'plan-approve' | 'plan-feedback' | 'permission' | 'message' | 'command';
export const RESPOND_KINDS: readonly RespondKind[] = ['question', 'plan-approve', 'plan-feedback', 'permission', 'message', 'command'];

/** Why a kind the level allows is missing from `accepts`. */
export type RespondLimit = 'no-permission-hooks' | 'not-interactive';
export const RESPOND_LIMIT_NAMES: readonly RespondLimit[] = ['no-permission-hooks', 'not-interactive'];

/** The kinds each level allows. Each level allows what the one before it does. */
export const LEVEL_KINDS: Record<RespondLevel, readonly RespondKind[]> = {
  off: [],
  questions: ['question', 'message'],
  'questions-and-plans': ['question', 'message', 'plan-approve', 'plan-feedback'],
  everything: ['question', 'message', 'plan-approve', 'plan-feedback', 'permission', 'command'],
};

/** Whether and how far a session can be answered from Podium (Report.session.respond). */
export interface RespondInfo {
  level: RespondLevel;
  /** What the session takes now: the level's kinds, less what `limits` removes; empty while the activityFeed option is off. */
  accepts: RespondKind[];
  limits: RespondLimit[];
}

/** The kinds a level allows once the limits are applied. */
export function acceptsFor(level: RespondLevel, limits: readonly RespondLimit[], activityFeed: boolean): RespondKind[] {
  if (!activityFeed || limits.includes('not-interactive')) return [];
  const drop: RespondKind[] = limits.includes('no-permission-hooks') ? ['plan-approve', 'permission'] : [];
  return LEVEL_KINDS[level].filter((k) => !drop.includes(k));
}

export type AskKind = 'question' | 'plan' | 'permission';

export interface AskOption {
  label: string;
  description: string;
  preview: string | null;
}

export interface AskQuestion {
  question: string;
  header: string;
  multiSelect: boolean;
  options: AskOption[];
}

/**
 * One thing a session waits on its person for that Podium can answer. Its id is the tool call's `tool_use_id`.
 * Redacted by the reporter, and cut to RESPOND_LIMITS with a visible marker.
 */
export interface Ask {
  id: string;
  kind: AskKind;
  /** The loop that asked: set for a subagent's permission prompt; null for the main loop. */
  agentId: string | null;
  openedAt: number;
  questions?: AskQuestion[];
  plan?: { text: string; filePath: string | null };
  /** The tool and its arguments; `cut` when anything was cut off, and then Podium cannot allow it. */
  tool?: { name: string; input: Record<string, unknown>; cut: boolean };
}

export const RESPOND_LIMITS = {
  asks: 8,
  questions: 4,
  options: 4,
  question: 1000,
  header: 40,
  label: 200,
  description: 1000,
  preview: 4000,
  plan: 40_000,
  toolInput: 20_000,
  /** A typed answer, a deny reason, a close's answer summary. */
  answer: 2000,
  /** A message, a reply in place of an answer, plan feedback. */
  message: 20_000,
  /** Messages and commands waiting for one session. */
  deliveries: 20,
  /** The longest a held request for an answer waits, in seconds ($.http.fetch gives up at 30). */
  holdSeconds: 20,
} as const;

/** What a delivery carries. `reply` is a message sent in place of an answer. */
export type DeliveryKind = 'question' | 'reply' | 'plan-approve' | 'plan-feedback' | 'allow-once' | 'deny' | 'message' | 'command';
export const DELIVERY_KINDS: readonly DeliveryKind[] = ['question', 'reply', 'plan-approve', 'plan-feedback', 'allow-once', 'deny', 'message', 'command'];

/** One question's answer by position: the chosen options' indexes, a typed answer, or null for skipped. */
export type QuestionAnswer = { options: number[] } | { text: string } | null;

export type PlanMode = 'auto' | 'acceptEdits' | 'default';
export const PLAN_MODES: readonly PlanMode[] = ['auto', 'acceptEdits', 'default'];

export type PodiumCommand = 'clear' | 'compact';
export const PODIUM_COMMANDS: readonly PodiumCommand[] = ['clear', 'compact'];

/** One answer or message sent from Podium, as the server hands it to the mod. */
export interface Delivery {
  id: string;
  /** The ask it answers; null for a message or a command. */
  askId: string | null;
  /** Who sent it: a person's name, or `Admin` for the admin secret. */
  by: string;
  at: number;
  kind: DeliveryKind;
  answers?: QuestionAnswer[];
  mode?: PlanMode;
  text?: string;
  command?: PodiumCommand;
}

/** What became of a delivery, as the mod reports it. */
export type DeliveryResult = 'took' | 'queued' | 'not-taken' | 'refused' | 'closed';
export const DELIVERY_RESULTS: readonly DeliveryResult[] = ['took', 'queued', 'not-taken', 'refused', 'closed'];

/** How an ask closed without an answer from Podium. */
export type AskCloseOutcome = 'terminal' | 'closed' | 'ended';

export interface AskClose {
  outcome: AskCloseOutcome;
  at: number;
  /** A short summary of the terminal's answer: a question's answers joined with "; ", `No, keep planning`, `allowed` or `denied`. */
  answer?: string | null;
  /** True for a plan approved in the terminal (which mode is not known). */
  planApproved?: boolean;
}

// ---- Orchestrator messaging (#347, SPEC 5.3, 6.2, 7.7) --------------------------------------

export const PEER_LIMITS = {
  /** The longest message the server takes; the Admin's limit is at most this. */
  message: 20_000,
  /** An orchestrator's reason when it asks for a right. */
  reason: 1000,
  /** A `to` address, `name@machine`. */
  address: 200,
  /** Peer deliveries in one reply. */
  deliveries: 20,
  /** Open requests in one reply. */
  requests: 20,
  /** The OS string in a report. */
  os: 80,
} as const;

/** A right one reporter has to another: none, can see, can send with approval (`ask`), can send. Sending includes seeing. */
export type PeerLevel = 'none' | 'see' | 'ask' | 'send';
export const PEER_LEVELS: readonly PeerLevel[] = ['none', 'see', 'ask', 'send'];

/** One orchestrator, as a message names its sender. */
export interface PeerParty {
  name: string;
  machine: string;
  owner: string;
  /** The sender's short session id, for `name@machine#id`; absent from a server older than #500. */
  id?: string;
}

/**
 * Something for this session's orchestrator from the messaging side, in the report reply. `message` is another
 * orchestrator's text, to be framed by the mod (SPEC 5.3); `notice` is Podium's own sentence about one of this
 * orchestrator's messages or requests (dropped, declined, answered), with `from` null. Its result goes to the peer
 * result route, never responding's.
 */
export interface PeerDelivery {
  id: string;
  kind: 'message' | 'notice';
  at: number;
  from: PeerParty | null;
  text: string;
}

/** What became of a peer delivery, as the mod reports it. */
export type PeerResult = 'took' | 'queued' | 'refused';
export const PEER_RESULTS: readonly PeerResult[] = ['took', 'queued', 'refused'];

/** A request the owner answers: an Admin's proposed right, an orchestrator's request for one, a message waiting for approval. */
export type PeerRequestKind = 'proposal' | 'access' | 'message';

/** How an owner answers a request: allow a proposal or an access request, deliver a message, or decline either. */
export type PeerAnswer = 'allow' | 'decline' | 'deliver';
export const PEER_ANSWERS: readonly PeerAnswer[] = ['allow', 'decline', 'deliver'];

/** One open request, as the owner's sessions on the machine it concerns are told of it. A reporter is named by its machine, an orchestrator by its name too. */
export interface PeerRequest {
  id: string;
  kind: PeerRequestKind;
  at: number;
  /** The reporter that would get the right, or the sender of a message. */
  from: { machine: string; name: string | null };
  /** The reporter the right is to, or the receiver of a message. */
  to: { machine: string; name: string | null };
  /** The right proposed or asked for; null for a message. */
  level: PeerLevel | null;
  /** Who asked: `Admin` for a proposal, the orchestrator's name for an access request or a message. */
  by: string;
  /** An orchestrator's reason, for an access request. */
  reason: string | null;
  /** The message's text, for a message waiting for approval. */
  text: string | null;
}

/** The reply to an accepted report. Older servers send only some of it. */
export interface ReportReply {
  ok: true;
  serverTime: number;
  ackedEvents: number;
  sessionId: string;
  liveSessions: number;
  serverVersion: string;
  /** The commit of a dev build of the server (#400); null for a release. Older servers do not send it. */
  serverBuild?: string | null;
  reporterSupport: { min: string; max: string };
  reporterCompat: 'ok' | 'outdated' | 'newer' | 'unknown';
  watch: string[];
  /** Whether the server takes answers for this session now; the mod announces asks only while it is true. */
  respond: boolean;
  /** Messages and commands from Podium waiting for this session, oldest first; empty while `respond` is false. */
  deliveries: Delivery[];
  /** Whether this session's orchestrator can take part in messaging now (#347): authentication on, the Admin's flag on, the session owned by a person, and the `peers` option on. */
  peers?: boolean;
  /** Messages and notices for this orchestrator, oldest first, handed over only while it is idle; empty while `peers` is false. */
  peerDeliveries?: PeerDelivery[];
  /** The owner's open requests about this session's reporter, for a toast and `/podium allow|decline|deliver`; empty while `peers` is false. */
  peerRequests?: PeerRequest[];
}

// <protocol:end>

