{
  "name": "podium-reporter",
  "version": "1.2.2",
  "description": "Reports this Claude Code session (model, effort, plan, agents, context, cost, git, failures) to a local Podium fleet console.",
  "types": "./types/index.d.ts",
  "author": {
    "name": "Ed Engelking"
  },
  "userConfig": {
    "serverUrl": {
      "type": "string",
      "title": "Podium server URL",
      "description": "Where the reporter posts session reports.",
      "default": "http://127.0.0.1:4317"
    },
    "token": {
      "type": "string",
      "title": "Podium token",
      "description": "Sent as X-Podium-Token. Use the token the server owner made for you in Podium Admin (it only works with your user name), or the server's admin secret on a single-user setup. Leave empty when the server has no token. A PODIUM_TOKEN environment variable set in the terminal overrides this at a session's first start (with PODIUM_USER).",
      "default": "",
      "sensitive": true
    },
    "userName": {
      "type": "string",
      "title": "Your name in Podium",
      "description": "The name the server owner gave you when they made your token. The server accepts your reports only when the token and this name match. Leave empty on a single-user setup. A PODIUM_USER environment variable set in the terminal overrides this at a session's first start (with PODIUM_TOKEN).",
      "default": ""
    },
    "flushIntervalMs": {
      "type": "number",
      "title": "Report interval (ms)",
      "description": "Minimum time between reports while something changes.",
      "default": 1000
    },
    "heartbeatMs": {
      "type": "number",
      "title": "Heartbeat (ms)",
      "description": "Report at least this often even when nothing changed.",
      "default": 5000
    },
    "sessionName": {
      "type": "string",
      "title": "Session name",
      "description": "Display name for this machine's sessions. Usually left empty.",
      "default": ""
    },
    "showStatus": {
      "type": "boolean",
      "title": "Status line",
      "description": "Show the reporter's state under the prompt: 'podium v<version> ● N live', or '○ offline', '○ connecting' or '○ token refused' after the version. A '· update mod', '· upgrade server' or '· update available' hint follows when the versions do not match.",
      "default": true
    },
    "explainFailures": {
      "type": "boolean",
      "title": "Explain failures",
      "description": "Ask a small model to explain each failure (costs tokens). Off by default.",
      "default": false
    },
    "fullPrompts": {
      "type": "boolean",
      "title": "Send full prompts and answers",
      "description": "Send each agent's whole task prompt and final answer (up to 20,000 characters each, secrets redacted) so the console can show them in full. Off by default: only the first 400 characters are sent.",
      "default": false
    },
    "activityFeed": {
      "type": "boolean",
      "title": "Send an agent's recent activity",
      "description": "While someone has an agent's panel open in Podium, send that agent's recent tool calls and the text it writes between them (the last 20, each cut to 300 characters, secrets redacted). Nothing is sent for an agent nobody is watching, and the server keeps it in memory only. Off by default.",
      "default": false
    },
    "fileDiff": {
      "type": "boolean",
      "title": "Send a file's diff on request",
      "description": "When the owner of a session opens a changed file in Podium's Files list, read that one file's diff and send it. Anything that looks like a secret is replaced with [redacted] before it leaves this machine, and .env, key and credentials files are never sent. Nothing is sent for a file nobody opens, and the server keeps no copy. Off by default.",
      "default": false
    },
    "respond": {
      "type": "string",
      "title": "Respond from Podium",
      "description": "What this session accepts from Podium, sent by its owner or an Admin. off: Nothing. The default. questions: Answers to questions, and new messages while idle. questions-and-plans: The above, plus approving or rejecting a plan. everything: The above, plus allowing or denying a tool (allow once only), and /clear, /compact. Needs 'Send an agent's recent activity' on too, and the Podium server's Respond from Podium switch.",
      "options": [
        "off",
        "questions",
        "questions-and-plans",
        "everything"
      ],
      "default": "off"
    },
    "peers": {
      "type": "boolean",
      "title": "Message my other orchestrators",
      "description": "Let this machine's orchestrators message your other orchestrators through Podium, within the rights you set in Podium > My reporters. Gives the main loop three tools (podium_peers, podium_send, podium_request_access); a subagent's call is refused. A message is sent with secrets replaced by [redacted], and one that arrives starts a new turn once this session is idle, marked as another agent's text that cannot approve anything. Needs the Podium server's Orchestrator messaging switch. Off by default.",
      "default": false
    }
  }
}

